    private String nativeStatus(){String label=ApiRepository.voiceTitle((dubbing==null||dubbing.isEmpty())?(episode==null?"":episode.name):dubbing);String size=Ui.videoSizeHint(quality,episode==null?0:episode.duration);return "Серия "+number(wantedEpisode)+(label.isEmpty()?"":" · "+label)+(quality>0?" · "+QualityPlus.name(quality):"")+(size.isEmpty()?"":" · "+size);}
    private String qualityLabel(){return quality>0?quality+"p":"Качество";}
    private String voiceLabel(){String v=ApiRepository.voiceTitle(dubbing);if(v.isEmpty()&&episode!=null){v=ApiRepository.voiceTitle(episode.name);if(v.isEmpty())v=ApiRepository.cleanLabel(episode.name);}if(v.isEmpty()&&!yummyVersion.isEmpty())v=yummyVersion;if(v.isEmpty())return "Озвучка";return v.length()>9?v.substring(0,8)+"…":v;}
    private void chooseQualityOverlay(){if(episode==null){Ui.toast(this,"Серия ещё не выбрана");return;}if(nativeMode&&!episode.streams.isEmpty()){ArrayList<Integer> qs=new ArrayList<>(episode.streams.keySet());ArrayList<String> labels=new ArrayList<>();int curIndex=0;for(int i=0;i<qs.size();i++){int q=qs.get(i);labels.add(QualityPlus.streamLabel(q));if(q==quality)curIndex=i;}Ui.singleChoice(this,"Разрешение видео",labels.toArray(new String[0]),curIndex,"Выбрать",pos->{if(pos<0||pos>=qs.size())return;int sel=qs.get(pos);if(qualitySelect!=null&&pos<qualitySelect.getCount())qualitySelect.setSelection(pos);if(sel!=quality){save(true);seekMs=player!=null?(int)player.getCurrentPosition():0;quality=sel;playNative(episode.streams.get(quality));updatePlayerControls();}});}else{Ui.toast(this,"Для текущего видео доступно только исходное разрешение");}}
    private void chooseVoiceOverlay(){if(episode==null){Ui.toast(this,"Серия ещё не выбрана");return;}ArrayList<String> names=new ArrayList<>();if(voiceGroups.isEmpty()&&!episode.variants.isEmpty()){buildVoiceGroups(episode,names);}else{for(ArrayList<Anime.Variant> g:voiceGroups){if(g==null||g.isEmpty())continue;Anime.Variant first=g.get(0);String v=ApiRepository.voiceTitle(first.name.isEmpty()?first.label():first.name);if(v.isEmpty())v=ApiRepository.voiceTitle(first.displayName);if(v.isEmpty())v=ApiRepository.cleanLabel(first.displayName);if(v.isEmpty())v=ApiRepository.cleanLabel(first.player);if(v.isEmpty())v="Вариант";names.add(v);}}if(names.isEmpty()||voiceGroups.isEmpty()){Ui.toast(this,"Для этой серии пока нет других озвучек");return;}int cur=voiceSelect!=null?voiceSelect.getSelectedItemPosition():0;cur=Math.max(0,Math.min(cur,names.size()-1));Ui.singleChoice(this,"Выберите озвучку",names.toArray(new String[0]),cur,"Выбрать",pos->{if(pos<0||pos>=voiceGroups.size()||voiceGroups.get(pos).isEmpty())return;if(voiceSelect!=null&&pos<voiceSelect.getCount())voiceSelect.setSelection(pos);Anime.Variant variant=voiceGroups.get(pos).get(0);String selectedVoice=ApiRepository.voiceSaveKey(variant);if(!selectedVoice.isEmpty()){YoruApp.app().store.setVoiceFor(anime,selectedVoice);YoruApp.app().store.rememberVoice(selectedVoice);}save(true);seekMs=nativeMode&&player!=null?(int)player.getCurrentPosition():browserTime*1000;showVariant(variant);updatePlayerControls();});}
    private int resumeFor(double ep){JSONObject h=YoruApp.app().store.progress(anime);if(Double.compare(h.optDouble("episode",-1),ep)!=0)return 0;int time=h.optInt("time"),duration=h.optInt("duration");if(duration>120&&time>duration-45)return 0;return time*1000;}
    private int buildVoiceGroups(Anime.Episode e,ArrayList<String> names){voiceGroups.clear();String own=YoruApp.app().store.voiceFor(anime);String preferred=dubbing==null||dubbing.isEmpty()?(own.isEmpty()?YoruApp.app().store.voicePreference():own):dubbing;boolean strict=YoruApp.app().store.onlyPreferredVoice()&&!ApiRepository.voiceKey(preferred).isEmpty();int selected=buildVoiceGroupsInternal(e,names,preferred,strict);if(voiceGroups.isEmpty()&&strict){names.clear();try{YoruApp.app().store.onlyPreferredVoice(false);}catch(Exception ignored){}selected=buildVoiceGroupsInternal(e,names,"",false);if(status!=null)status.setText("ÐÑÐ±ÑÐ°Ð½Ð½Ð°Ñ Ð¾Ð·Ð²ÑÑÐºÐ° Ð½ÐµÐ´Ð¾ÑÑÑÐ¿Ð½Ð° â Tsuyu Ð½Ð°ÑÑÐ» Ð´ÑÑÐ³Ð¸Ðµ Ð²Ð°ÑÐ¸Ð°Ð½ÑÑ");}return selected;}
    private int buildVoiceGroupsInternal(Anime.Episode e,ArrayList<String> names,String preferred,boolean strict){voiceGroups.clear();LinkedHashMap<String,ArrayList<Anime.Variant>> map=new LinkedHashMap<>();for(Anime.Variant v:SourceEngine.sortVariants(e==null?null:e.variants)){if(v==null)continue;String raw=v.name+" "+v.displayName+" "+v.player;if(strict&&!(preferred.startsWith("src:")?preferred.equals("src:"+SourceEngine.sourceId(v.player)):ApiRepository.voiceMatches(preferred,raw)))continue;String voice=ApiRepository.voiceTitle(v.name.isEmpty()?v.label():v.name);if(voice.isEmpty())voice=ApiRepository.voiceTitle(v.displayName);if(voice.isEmpty())voice=ApiRepository.cleanLabel(v.displayName);if(voice.isEmpty())voice=ApiRepository.cleanLabel(v.player);String key=ApiRepository.voiceKey(voice);if(key.isEmpty()){key="unknown:"+Integer.toHexString((v.url==null?"":v.url).hashCode());if(voice.isEmpty())voice="Вариант "+(map.size()+1);}ArrayList<Anime.Variant> group=map.get(key);if(group==null){group=new ArrayList<>();map.put(key,group);}group.add(v);}int selected=0,index=0;for(ArrayList<Anime.Variant> group:map.values()){voiceGroups.add(group);Anime.Variant first=group.get(0);String voice=ApiRepository.voiceTitle(first.name.isEmpty()?first.label():first.name);if(voice.isEmpty())voice=ApiRepository.voiceTitle(first.displayName);if(voice.isEmpty())voice=ApiRepository.cleanLabel(first.displayName);if(voice.isEmpty())voice=ApiRepository.cleanLabel(first.player);if(voice.isEmpty())voice="Вариант "+(index+1);names.add(voice);String preferredCheck=preferred;if(!preferredCheck.isEmpty()){boolean match=false;for(Anime.Variant vv:group){String raw=vv.name+" "+vv.displayName+" "+vv.player;if(preferredCheck.startsWith("src:")?preferredCheck.equals("src:"+SourceEngine.sourceId(vv.player)):ApiRepository.voiceMatches(preferredCheck,raw)||ApiRepository.voiceMatches(preferredCheck,voice)){match=true;break;}}if(match)selected=index;}index++;}return selected;}
